insert into public.ark60_content(day_number,module,title,status,payload,published_at,updated_at)
values(9,'listening','IELTS Listening Test 199','published',$json${"version":"listening-test-199-v1","test_code":"TEST-199","audio_url":"https://ia903206.us.archive.org/28/items/test-199-ready/TEST_199_ready.mp3","total_questions":40,"audio_once":true,"sections":[{"number":1,"label":"SECTION 1","range":"Questions 1–10","blocks":[{"kind":"mcq","range":"Questions 1–8","instruction":"Choose the correct answer, A, B or C.","title":"Great Sandcastle Center","questions":[{"q":1,"text":"The centre has enough accommodation for","options":{"A":"18 people.","B":"20 people.","C":"38 people."}},{"q":2,"text":"The meeting room is currently","options":{"A":"unavailable.","B":"flooded.","C":"booked."}},{"q":3,"text":"Visitors must tell the centre in advance if they want to","options":{"A":"use the centre's kitchen.","B":"have meals cooked for them.","C":"eat at restaurants outside."}},{"q":4,"text":"All visitors on the farm can","options":{"A":"get information about organic farming.","B":"help to feed the animals.","C":"watch a tractor demonstration."}},{"q":5,"text":"On the survival course, people have to","options":{"A":"learn to use a map.","B":"find their own food.","C":"run through woodland."}},{"q":6,"text":"From the centre, it is easy to walk to","options":{"A":"Exmoor National Park.","B":"the beach.","C":"a cycling route."}},{"q":7,"text":"If the weather is bad, visitors can go to a","options":{"A":"cinema.","B":"theatre.","C":"museum."}},{"q":8,"text":"Groups who wish to stay at the centre must pay","options":{"A":"part of the cost in advance.","B":"all of the cost in advance.","C":"all of the cost on arrival."}}]},{"kind":"notes","range":"Questions 9–10","instruction":"Complete the notes below.","word_limit":"Write ONE WORD AND/OR A NUMBER for each answer.","title":"Address","items":[["Winsham Farm, ",{"q":9}," Road"],["near Sherbourne ",{"q":10}]]}]},{"number":2,"label":"SECTION 2","range":"Questions 11–20","blocks":[{"kind":"table","range":"Questions 11–16","instruction":"Complete the table below.","word_limit":"Write NO MORE THAN THREE WORDS AND/OR A NUMBER for each answer.","title":"Vacation Jobs","headers":["Vacation Job","Main Advantage","Main Disadvantage","Recommendation"],"rows":[[["Stocktaking"],[{"q":11}],["tiring"],[{"q":12}]],[["Office work"],["air-conditioning"],[{"q":13}],["choose a ",{"q":14}]],[["Theme park attendant"],[{"q":15}],["rude customers"],[{"q":16}]]]},{"kind":"mcq","range":"Questions 17–20","instruction":"Choose the correct answer, A, B or C.","title":"Peter’s Vacation Job","questions":[{"q":17,"text":"Peter learned about the job","options":{"A":"from a college friend.","B":"on the computer.","C":"from a student job centre."}},{"q":18,"text":"Peter mainly enjoyed the job because it was","options":{"A":"easy.","B":"challenging.","C":"unusual."}},{"q":19,"text":"The job's most interesting aspect was","options":{"A":"learning about the environment.","B":"working with children.","C":"caring for the animals."}},{"q":20,"text":"Peter has decided that next vacation he","options":{"A":"won't take a job.","B":"will work at the zoo.","C":"will work elsewhere."}}]}]},{"number":3,"label":"SECTION 3","range":"Questions 21–30","blocks":[{"kind":"mcq","range":"Questions 21–26","instruction":"Choose the correct answer, A, B or C.","title":"Voice Training for Drama Students","questions":[{"q":21,"text":"Ed is giving the voice coaching workshop in order to get","options":{"A":"a new job.","B":"a qualification.","C":"a promotion."}},{"q":22,"text":"According to Fiona, the seating pattern that Ed chooses","options":{"A":"should be illustrated visually.","B":"has to be explained in detail.","C":"is not particularly important."}},{"q":23,"text":"Fiona and Ed agree that in the first activity, the students","options":{"A":"may feel uncomfortable.","B":"like to make group contact.","C":"must focus on themselves."}},{"q":24,"text":"Fiona and Ed agree that in the second activity, Ed should","options":{"A":"insist which students work together.","B":"tell students to prepare a speech.","C":"include a focus on breath control."}},{"q":25,"text":"What does Fiona suggest about working in a big space?","options":{"A":"It could be outside or inside.","B":"It is best to go to somewhere like a park.","C":"It is useful for getting actors to shout."}},{"q":26,"text":"What does Fiona think of Ed's selection of texts?","options":{"A":"It should include more classical texts.","B":"It needs to focus on a single emotion.","C":"It has to cover a wider range."}}]},{"kind":"matching","range":"Questions 27–30","instruction":"What disadvantage do the speakers identify for each of the following textbooks? Choose the correct letter A–G for each.","word_limit":"Choose ONE letter, A–G, for each textbook.","title":"Textbook Disadvantages","choices":{"A":"too expensive","B":"too limited","C":"prejudiced","D":"unavailable","E":"unrealistic","F":"out of date","G":"too detailed"},"items":[{"q":27,"text":"Vocal Instruction"},{"q":28,"text":"Improve Your Accent"},{"q":29,"text":"Actors’ Handbook"},{"q":30,"text":"Confident Voice Delivery"}]}]},{"number":4,"label":"SECTION 4","range":"Questions 31–40","blocks":[{"kind":"notes_groups","range":"Questions 31–40","instruction":"Complete the notes below.","word_limit":"Write ONE WORD ONLY for each answer.","title":"Food Safety Standards","groups":[{"heading":"Risk Assessment","intro":"Scientists have to consider potential problems with:","items":[["the products’ ",{"q":31}," (could they attract harmful bacteria?)"],["method of preparation (will it eliminate harmful micro-organisms?)"],["how products are ",{"q":32}," and distributed"],["supermarkets (e.g. changes in ",{"q":33}," affecting the condition of frozen food)"],["end-users (how is food usually handled in the home?)"]]},{"heading":"Factors Affecting Food Consumption — Legislation and Consumer Attitudes","items":[["e.g. dislike of additives + growth of the ",{"q":34}," food market in Australia"]]},{"heading":"The food industry","items":[["supermarkets may use price or ",{"q":35}," as their selling strategy (but the main concern is profitability)"]]},{"heading":"The mass media","items":[["now the main source of ",{"q":36}," for many"],["negative effect because not objective: concern for ",{"q":37}],["news is now a form of ",{"q":38}," which can mislead the public"],["few programmes deal with food safety or ",{"q":39}]]},{"heading":"Personal opinion","items":[["Importance of education: as with benefits of exercise, many children can influence their ",{"q":40}]]}]}]}],"answer_key":{"1":["C"],"2":["A"],"3":["B"],"4":["A"],"5":["B"],"6":["C"],"7":["C"],"8":["A"],"9":["COTEHELE"],"10":["SH12 1LQ","SH121LQ"],"11":["travelling","traveling"],"12":["get good shoes"],"13":["wearing formal clothes"],"14":["large office"],"15":["good pay"],"16":["live nearby"],"17":["B"],"18":["C"],"19":["B"],"20":["A"],"21":["B"],"22":["C"],"23":["C"],"24":["C"],"25":["A"],"26":["C"],"27":["F"],"28":["B"],"29":["D"],"30":["E"],"31":["ingredients"],"32":["stored"],"33":["temperature"],"34":["organic"],"35":["image"],"36":["information"],"37":["sales"],"38":["entertainment"],"39":["nutrition"],"40":["parents"]}}$json$::jsonb,now(),now())
